:root {
    --bg-color: #2c3e50;
    --taskbar-bg: rgba(0, 0, 0, 0.7);
    --window-bg: rgba(255, 255, 255, 0.9);
    --accent-color: #3498db;
    --text-color: #333;
}

body, html {
    margin: 0;
    padding: 0;
    width: 100%;
    height: 100%;
    overflow: hidden;
    font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
}

#desktop {
    width: 100vw;
    height: 100vh;
    background: linear-gradient(135deg, #1e3c72 0%, #2a5298 100%);
    position: relative;
    padding: 20px;
    box-sizing: border-box;
    display: flex;
    flex-direction: column;
    flex-wrap: wrap;
    align-content: flex-start;
    gap: 20px;
}

.icon {
    width: 80px;
    height: 90px;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    border-radius: 8px;
    transition: background 0.2s;
    user-select: none;
}

.icon:hover {
    background: rgba(255, 255, 255, 0.2);
}

.icon-img {
    font-size: 40px;
    margin-bottom: 5px;
}

.icon-label {
    color: white;
    font-size: 12px;
    text-shadow: 1px 1px 2px rgba(0,0,0,0.8);
    text-align: center;
}

#taskbar {
    position: fixed;
    bottom: 0;
    left: 0;
    width: 100%;
    height: 45px;
    background: var(--taskbar-bg);
    backdrop-filter: blur(10px);
    display: flex;
    align-items: center;
    padding: 0 10px;
    box-sizing: border-box;
    z-index: 1000;
    color: white;
}

#start-button {
    font-size: 24px;
    cursor: pointer;
    padding: 0 10px;
    height: 100%;
    display: flex;
    align-items: center;
}

#running-apps {
    flex-grow: 1;
    display: flex;
    gap: 5px;
    margin-left: 10px;
}

.taskbar-item {
    background: rgba(255, 255, 255, 0.1);
    padding: 5px 15px;
    border-radius: 4px;
    font-size: 13px;
    cursor: pointer;
}

#system-tray {
    font-size: 13px;
}

/* Window Styles */
.window {
    position: absolute;
    min-width: 300px;
    min-height: 200px;
    background: var(--window-bg);
    border-radius: 8px;
    box-shadow: 0 10px 30px rgba(0,0,0,0.5);
    display: flex;
    flex-direction: column;
    overflow: hidden;
    z-index: 10;
}

.window-header {
    height: 35px;
    background: #eee;
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0 10px;
    cursor: move;
    user-select: none;
}

.window-title {
    font-size: 13px;
    font-weight: bold;
    color: #333;
}

.window-controls {
    display: flex;
    gap: 8px;
}

.control-btn {
    width: 12px;
    height: 12px;
    border-radius: 50%;
    cursor: pointer;
    border: none;
    outline: none;
    display: inline-block;
    transition: transform 0.2s;
}

.btn-close { background: #ff5f56; }
.btn-min { background: #ffbd2e; }
.btn-max { background: #27c93f; }

.control-btn:hover {
    transform: scale(1.2);
    filter: brightness(1.1);
}

.window-content {
    flex-grow: 1;
    padding: 15px;
    color: var(--text-color);
    overflow: auto;
    background: rgba(255, 255, 255, 0.5);
}

.window-header {
    background: rgba(0, 0, 0, 0.1);
    padding: 8px 12px;
    display: flex;
    justify-content: space-between;
    align-items: center;
    cursor: move;
    user-select: none;
}
}

.close-btn {
    background: rgba(255, 255, 255, 0.2);
    border: none;
    color: white;
    border-radius: 4px;
    cursor: pointer;
    width: 24px;
    height: 24px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 14px;
}

.close-btn:hover {
    background: rgba(255, 0, 0, 0.5);
}

.window-content {
    flex-grow: 1;
    position: relative;
}
/* Taskbar and Window enhancements */
.taskbar-item {
    background: rgba(255, 255, 255, 0.1);
    padding: 5px 15px;
    border-radius: 4px;
    font-size: 13px;
    cursor: pointer;
    display: flex;
    align-items: center;
    gap: 8px;
    color: white;
    border: 1px solid rgba(255, 255, 255, 0.1);
    transition: background 0.2s;
}

.taskbar-item:hover {
    background: rgba(255, 255, 255, 0.2);
}

.taskbar-item.active {
    background: rgba(255, 255, 255, 0.3);
    border-bottom: 2px solid var(--accent-color);
}

/* Terminal Style */
.terminal-output {
    background: #1a1a1a;
    color: #00ff00;
    font-family: 'Courier New', Courier, monospace;
    padding: 10px;
    height: 100%;
    overflow-y: auto;
    white-space: pre-wrap;
}

.terminal-input-line {
    display: flex;
    gap: 5px;
}

.terminal-input-line input {
    background: transparent;
    border: none;
    color: #00ff00;
    font-family: inherit;
    outline: none;
    flex-grow: 1;
}

.notepad-container {
    display: flex;
    flex-direction: column;
    height: 100%;
    width: 100%;
}

.notepad-toolbar {
    display: flex;
    gap: 10px;
    padding-bottom: 10px;
    border-bottom: 1px solid #ccc;
    margin-bottom: 10px;
}

.notepad-toolbar button {
    padding: 4px 12px;
    border: none;
    border-radius: 4px;
    background: #eee;
    cursor: pointer;
    font-size: 12px;
}

.notepad-toolbar button:hover {
    background: #ddd;
}

#notepad-editor {
    flex-grow: 1;
    width: 100%;
    height: 100%;
    border: none;
    resize: none;
    padding: 10px;
    box-sizing: border-box;
    font-family: monospace;
    font-size: 14px;
    outline: none;
    background: #fff;
}

/* Settings Style */
.settings-panel {
    display: flex;
    flex-direction: column;
    gap: 15px;
}

.color-swatch {
    width: 30px;
    height: 30px;
    border-radius: 50%;
    cursor: pointer;
    border: 2px solid white;
    display: inline-block;
}

/* Todo App Styles */
.todo-container {
    display: flex;
    flex-direction: column;
    gap: 10px;
    padding: 10px;
    height: 100%;
    box-sizing: border-box;
    overflow-y: auto;
}
.todo-input-group {
    display: flex;
    gap: 5px;
}
.todo-input-group input {
    flex-grow: 1;
    padding: 8px;
    border: 1px solid #ccc;
    border-radius: 4px;
    background: #f9f9f9;
    color: #333;
}
.todo-input-group button {
    padding: 8px 15px;
    background: #4CAF50;
    color: white;
    border: none;
    border-radius: 4px;
    cursor: pointer;
}
.todo-list {
    list-style: none;
    padding: 0;
    margin: 0;
}
.todo-item {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 8px;
    border-bottom: 1px solid #eee;
    background: white;
    color: #333;
    margin-bottom: 2px;
    border-radius: 4px;
}
.todo-item.completed span {
    text-decoration: line-through;
    color: #888;
}
.todo-item span {
    flex-grow: 1;
    cursor: pointer;
}
.todo-item button {
    background: #ff5f56;
    color: white;
    border: none;
    border-radius: 4px;
    padding: 2px 8px;
    cursor: pointer;
}


/* File Explorer Styles */
.file-explorer {
    display: flex;
    flex-direction: column;
    height: 100%;
}

.explorer-toolbar {
    padding: 10px;
    background: #eee;
    display: flex;
    gap: 5px;
    border-bottom: 1px solid #ccc;
}

.explorer-toolbar button {
    padding: 5px 10px;
    cursor: pointer;
}

.explorer-content {
    flex-grow: 1;
    padding: 10px;
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(70px, 1fr));
    gap: 10px;
    overflow-y: auto;
}

.file-item {
    display: flex;
    flex-direction: column;
    align-items: center;
    padding: 10px;
    cursor: pointer;
    border-radius: 4px;
    text-align: center;
}

.file-item:hover {
    background: rgba(0,0,0,0.1);
}

.file-icon {
    font-size: 30px;
}

.file-name {
    font-size: 12px;
    word-break: break-all;
}

/* Terminal & Notepad Styles */
.terminal-container {
    background: #000;
    color: #0f0;
    height: 100%;
    display: flex;
    flex-direction: column;
    font-family: 'Courier New', Courier, monospace;
}
.terminal-output {
    flex-grow: 1;
    overflow-y: auto;
    padding: 10px;
}
.terminal-input-area {
    display: flex;
    background: #111;
    padding: 5px;
}
.prompt {
    color: #0f0;
    margin-right: 10px;
}
.terminal-input-area input {
    background: transparent;
    border: none;
    color: #0f0;
    flex-grow: 1;
    outline: none;
    font-family: inherit;
}
.notepad-container {
    display: flex;
    flex-direction: column;
    height: 100%;
}
.notepad-toolbar {
    padding: 5px;
    background: #ddd;
    border-bottom: 1px solid #ccc;
}
#note-editor {
    flex-grow: 1;
    border: none;
    padding: 10px;
    resize: none;
    outline: none;
    font-family: inherit;
    font-size: 16px;
}

/* Context Menu Styles */
#context-menu {
    position: absolute;
    background: white;
    border-radius: 8px;
    box-shadow: 0 5px 15px rgba(0,0,0,0.3);
    padding: 5px 0;
    min-width: 150px;
    z-index: 10000;
}

#context-menu ul {
    list-style: none;
    margin: 0;
    padding: 0;
}

#context-menu li {
    padding: 10px 15px;
    cursor: pointer;
    color: #333;
    transition: background 0.2s;
}

#context-menu li:hover {
    background: #f0f0f0;
}

#context-menu hr {
    margin: 5px 0;
    border: none;
    border-top: 1px solid #eee;
}

