/**
 * WebOS Pro - Kernel & Core
 * Architecture: Modular Kernel-based
 */

class VirtualFS {
    constructor() {
        this.storageKey = 'webos_fs';
        this.root = { type: 'dir', children: { 'documents': { type: 'dir', children: {} }, 'notes.txt': { type: 'file', content: 'Welcome to WebOS!' } } };
        this.load();
    }
    load() {
        try {
            const data = localStorage.getItem(this.storageKey);
            if (data) {
                this.root = JSON.parse(data);
            } else {
                this.save();
            }
        } catch (e) {
            console.error('Failed to load FS:', e);
            this.root = { type: 'dir', children: { 'documents': { type: 'dir', children: {} }, 'notes.txt': { type: 'file', content: 'Welcome to WebOS!' } } };
            this.save();
        }
    }
    save() { localStorage.setItem(this.storageKey, JSON.stringify(this.root)); }
    init() { console.log('FS initialized'); }
    mkdir(name) {
        if (name && !this.root.children[name]) {
            this.root.children[name] = { type: 'dir', children: {} };
            this.save();
            return true;
        }
        return false;
    }
    createFile(name) {
        if (name && !this.root.children[name]) {
            this.root.children[name] = { type: 'file', content: '' };
            this.save();
            return true;
        }
        return false;
    }
    writeFile(path, content) {
        const parts = path.split('/');
        let current = this.root;
        for (let i = 0; i < parts.length - 1; i++) {
            if (current.children[parts[i]] && current.children[parts[i]].type === 'dir') {
                current = current.children[parts[i]];
            } else {
                return false;
            }
        }
        const fileName = parts[parts.length - 1];
        if (current.children[fileName]) {
            current.children[fileName].content = content;
            this.save();
            return true;
        }
        return false;
    }
    init() { console.log('FS initialized'); }
}

class SystemManager {
    constructor(kernel) { this.kernel = kernel; }
    reboot() { location.reload(); }
}

class ProcessManager {
    constructor(kernel) {
        this.kernel = kernel;
        this.processes = new Map();
    }
    startProcess(appId, processInfo) {
        this.processes.set(appId, processInfo);
        this.kernel.ui.updateTaskbar();
    }
    stopProcess(appId) {
        this.processes.delete(appId);
        this.kernel.ui.updateTaskbar();
    }
    getRunningApps() {
        return Array.from(this.processes.entries()).map(([id, info]) => ({ id, name: info.name }));
    }
}

class KernelEngine {
    constructor() {
        this.fs = new VirtualFS();
        this.system = new SystemManager(this);
        this.processManager = new ProcessManager(this);
        this.ui = new UIController(this);
        this.apps = new AppManager(this);
    }
    init() {
        this.ui.init();
        this.apps.registerAll();
        this.fs.init();
    }
}

class AppManager {
    constructor(kernel) {
        this.kernel = kernel;
        this.apps = [
            { id: 'todo', name: 'Задачи', icon: '✅' },
            { id: 'explorer', name: 'Проводник', icon: '📂' },
            { id: 'terminal', name: 'Terminal', icon: '💻' },
            { id: 'notepad', name: 'Notepad', icon: '📝' },
            { id: 'browser', name: 'Browser', icon: '🌐' },
            { id: 'settings', name: 'Settings', icon: '⚙️' }
        ];
    }
    registerAll() {}
    launch(appId, params = {}) {
        const app = this.apps.find(a => a.id === appId);
        if (!app) return;
        let appInstance;
        if (appId === 'todo') appInstance = new TodoApp(this.kernel);
        else if (appId === 'explorer') appInstance = new FileExplorerApp(this.kernel);
        else if (appId === 'notepad') appInstance = new NotepadApp(this.kernel);
        else if (appId === 'terminal') appInstance = new TerminalApp(this.kernel);
        else if (appId === 'settings') appInstance = new SettingsApp(this.kernel);

        if (appInstance) {
            this.kernel.ui.createWindow(app.name, '', app.id);
            setTimeout(() => {
                const win = document.getElementById(`window-${appId}`);
                if (win) {
                    appInstance.render(win.querySelector('.window-content'), params);
                    this.kernel.processManager.startProcess(appId, app);
                }
            }, 50);
        }
    }
}

class UIController {
    constructor(kernel) {
        this.kernel = kernel;
        this.contextMenu = document.getElementById('context-menu');
        this.zIndexCounter = 100;
    }
    init() {
        this.updateClock();
        setInterval(() => this.updateClock(), 1000);
        const loader = document.getElementById('loading-screen');
        if (loader) loader.style.display = 'none';
        document.addEventListener('click', (e) => this.hideContextMenu(e));
        document.addEventListener('contextmenu', (e) => {
            e.preventDefault();
            this.showContextMenu(e.clientX, e.clientY);
        });
        this.initSearch();
    }
    initSearch() {
        const searchInput = document.getElementById('start-search');
        if (!searchInput) return;
        searchInput.addEventListener('input', (e) => {
            const term = e.target.value.toLowerCase();
            const items = document.querySelectorAll('.start-item');
            items.forEach(item => {
                const text = item.textContent.toLowerCase();
                item.style.display = text.includes(term) ? 'block' : 'none';
            });
        });
    }
    updateClock() {
        const clockEl = document.getElementById('clock');
        if (clockEl) clockEl.textContent = new Date().toLocaleTimeString();
    }
    toggleStartMenu() {
        document.getElementById('start-menu').classList.toggle('hidden');
    }
    showContextMenu(x, y) {
        this.contextMenu.style.top = x + 'px';
        this.contextMenu.style.left = y + 'px';
        this.contextMenu.classList.remove('hidden');
    }
    hideContextMenu(e) { this.contextMenu.classList.add('hidden'); }
    updateTaskbar() {
        const container = document.getElementById('running-apps');
        if (!container) return;
        container.innerHTML = '';
        this.kernel.processManager.getRunningApps().forEach(app => {
            const btn = document.createElement('button');
            btn.className = 'taskbar-item';
            btn.textContent = app.name;
            btn.onclick = () => this.focusWindow(app.id);
            container.appendChild(btn);
        });
    }
    focusWindow(appId) {
        const win = document.getElementById('window-' + appId);
        if (win) {
            if (win.style.display === 'none') {
                win.style.display = 'flex';
            }
            if (win.dataset.maximized === 'true') {
                win.style.width = '';
                win.style.height = '';
                win.style.top = '';
                win.style.left = '';
                win.dataset.maximized = 'false';
            }
            this.zIndexCounter++;
            win.style.zIndex = this.zIndexCounter;
        }
    }
    createWindow(title, content, appId) {
        const desktop = document.getElementById('desktop');
        const win = document.createElement('div');
        win.className = 'window';
        win.id = 'window-' + appId;
        win.style.zIndex = ++this.zIndexCounter;
        win.innerHTML = '<div class="window-header">' +
            '<span class="window-title">' + title + '</span>' +
            '<div class="window-controls">' +
                '<button class="control-btn btn-min">_</button>' +
                '<button class="control-btn btn-max">□</button>' +
                '<button class="control-btn btn-close">✕</button>' +
            '</div>' +
            '</div>' +
            '<div class="window-content"></div>';

        win.querySelector('.window-header').onmousedown = (e) => {
            if (e.target.className === 'window-title' || e.target.parentElement.className === 'window-header') {
                this.makeDraggable(win, win.querySelector('.window-header'));
            }
        };

        win.querySelector('.btn-close').onclick = () => {
            win.remove();
            this.kernel.processManager.stopProcess(appId);
        };
        win.querySelector('.btn-min').onclick = () => this.minimizeWindow(appId);
        win.querySelector('.btn-max').onclick = () => this.maximizeWindow(appId);

        win.onmousedown = () => this.focusWindow(appId);

        desktop.appendChild(win);
        return win;
    }

    minimizeWindow(appId) {
        const win = document.getElementById('window-' + appId);
        if (win) {
            win.style.display = 'none';
            win.dataset.minimized = 'true';
        }
    }

    maximizeWindow(appId) {
        const win = document.getElementById('window-' + appId);
        if (win) {
            if (win.dataset.maximized === 'true') {
                win.style.width = '';
                win.style.height = '';
                win.style.top = '';
                win.style.left = '';
                win.dataset.maximized = 'false';
            } else {
                win.style.width = '100%';
                win.style.height = 'calc(100vh - 45px)';
                win.style.top = '0';
                win.style.left = '0';
                win.dataset.maximized = 'true';
            }
        }
    }

    makeDraggable(win, header) {
        let offsetX = 0, offsetY = 0, startX = 0, startY = 0;
        header.onmousedown = (e) => {
            startX = e.clientX;
            startY = e.clientY;
            offsetX = e.clientX - win.offsetLeft;
            offsetY = e.clientY - win.offsetTop;

            const onMove = (e) => {
                win.style.left = (e.clientX - offsetX) + 'px';
                win.style.top = (e.clientY - offsetY) + 'px';
                win.style.margin = '0';
            };
            const onUp = () => {
                document.removeEventListener('mousemove', onMove);
                document.removeEventListener('mouseup', onUp);
            };
            document.addEventListener('mousemove', onMove);
            document.addEventListener('mouseup', onUp);
        };
    }

    changeWallpaper() {
        const colors = ['#2c3e50', '#e74c3c', '#27ae60', '#2980b9', '#8e44ad', '#f39c12'];
        const color = colors[Math.floor(Math.random() * colors.length)];
        document.body.style.background = 'linear-gradient(45deg, ' + color + ', #000)';
    }
}

class TodoApp {
    constructor(kernel) { this.kernel = kernel; }
    render(container) {
        container.innerHTML = '<div class="todo-container"><div class="todo-input-group"><input type="text" id="new-task" placeholder="Task..."><button id="add-task-btn" class="btn-primary">+</button></div><ul id="todo-list"></ul></div>';

        const fs = this.kernel.fs;
        let tasks = [];
        const todoFile = 'documents/todo.json';

        const loadTasks = () => {
            const parts = todoFile.split('/');
            const dir = fs.root.children[parts[0]];
            if (dir && dir.children[parts[1]]) {
                try {
                    tasks = JSON.parse(dir.children[parts[1]].content);
                } catch(e) { tasks = []; }
            }
        };

        const saveTasks = () => {
            fs.writeFile(todoFile, JSON.stringify(tasks));
        };

        const renderTasks = () => {
            const list = document.getElementById('todo-list');
            if (!list) return;
            list.innerHTML = '';
            tasks.forEach((task, index) => {
                const li = document.createElement('li');
                li.className = 'todo-item' + (task.completed ? ' completed' : '');
                li.innerHTML = `<span>${task.text}</span><button class="del-task">✕</button>`;
                li.querySelector('.del-task').onclick = (e) => {
                    e.stopPropagation();
                    tasks.splice(index, 1);
                    renderTasks();
                    saveTasks();
                };
                li.querySelector('span').onclick = () => {
                    tasks[index].completed = !tasks[index].completed;
                    renderTasks();
                    saveTasks();
                };
                list.appendChild(li);
            });
        };

        document.getElementById('add-task-btn').onclick = () => {
            const input = document.getElementById('new-task');
            const val = input.value;
            if (val.trim()) {
                tasks.push({ text: val, completed: false });
                input.value = '';
                renderTasks();
                saveTasks();
            }
        };

        loadTasks();
        renderTasks();
    }
}

class FileExplorerApp {
    constructor(kernel) { this.kernel = kernel; }
    render(container) {
        container.innerHTML = '<div class="file-explorer"><div class="explorer-toolbar"><button onclick="Kernel.fs.mkdir(\'new_folder\')">New Folder</button><button onclick="Kernel.fs.createFile(\'file.txt\')">New File</button></div><div id="explorer-files" class="explorer-content"></div></div>';
        this.refresh();
    }
    refresh() {
        const list = document.getElementById('explorer-files');
        if (!list) return; list.innerHTML = '';
        Object.keys(this.kernel.fs.root.children).forEach(name => {
            const item = this.kernel.fs.root.children[name];
            const div = document.createElement('div');
            div.className = `file-item ${item.type}`;
            div.innerHTML = `<span>${item.type === 'dir' ? '📁' : '📄'}</span><span>${name}</span>`;
            div.onclick = () => item.type === 'file' ? this.kernel.apps.launch('notepad', { filename: name }) : null;
            list.appendChild(div);
        });
    }
}

class NotepadApp {
    constructor(kernel) { this.kernel = kernel; }
    render(container, params) {
        container.innerHTML = '<div class="notepad-container"><div class="notepad-toolbar"><button id="note-new">New</button><button id="note-save">Save</button></div><textarea id="note-editor"></textarea></div>';
        const editor = document.getElementById('note-editor');
        if (params && params.filename) {
            const f = this.kernel.fs.root.children[params.filename];
            if (f) editor.value = f.content;
        }
        document.getElementById('note-new').onclick = () => editor.value = '';
        document.getElementById('note-save').onclick = () => {
            const name = prompt("Save as (filename):") || 'note.txt';
            this.kernel.fs.createFile(name);
            this.kernel.fs.writeFile(name, editor.value);
            alert('Saved!');
        };
    }
}

class TerminalApp {
    constructor(kernel) { this.kernel = kernel; }
    render(container) {
        container.innerHTML = '<div class="terminal-container"><div id="term-out" class="terminal-output"></div><div class="terminal-input-area"><span class="prompt">$</span><input type="text" id="term-input" autofocus></div></div>';
        document.getElementById('term-input').onkeydown = (e) => {
            if (e.key === 'Enter') {
                this.execute(e.target.value, document.getElementById('term-out'));
                e.target.value = '';
            }
        };
    }
    execute(cmd, output) {
        const line = document.createElement('div');
        line.textContent = `$ ${cmd}`;
        output.appendChild(line);
        const res = document.createElement('div');
        const parts = cmd.split(' ');
        switch (parts[0]) {
            case 'help': res.textContent = 'ls, clear, whoami, date, echo, mkdir, touch, cat'; break;
            case 'ls': res.textContent = Object.keys(this.kernel.fs.root.children).join(' '); break;
            case 'whoami': res.textContent = 'admin'; break;
            case 'date': res.textContent = new Date().toLocaleString(); break;
            case 'clear': output.innerHTML = ''; return;
            case 'echo': res.textContent = parts.slice(1).join(' '); break;
            case 'mkdir': this.kernel.fs.mkdir(parts[1]); res.textContent = 'OK'; break;
            case 'touch': this.kernel.fs.createFile(parts[1]); res.textContent = 'OK'; break;
            case 'cat':
                const f = this.kernel.fs.root.children[parts[1]];
                res.textContent = f ? f.content : 'No file'; break;
            default: res.textContent = 'Unknown command';
        }
        output.appendChild(res);
        output.scrollTop = output.scrollHeight;
    }
}

