/**
 * App Manager
 */
import { TodoApp } from './todo.js';
import { FileExplorerApp } from './explorer.js';
import { BrowserApp } from './browser.js';
import { NotepadApp } from './notepad.js';
import { TerminalApp } from './terminal.js';
import { SettingsApp } from './settings.js';

export class AppManager {
    constructor(kernel) {
        this.kernel = kernel;
        this.apps = [
            { id: 'todo', name: 'Задачи', icon: '✅' },
            { id: 'explorer', name: 'Проводник', icon: '📂' },
            { id: 'terminal', name: 'Terminal', icon: '💻' },
            { id: 'notepad', name: 'Notepad', icon: '📝' },
            { id: 'browser', name: 'Browser', icon: '🌐' },
            { id: 'settings', name: 'Settings', icon: '⚙️' }
        ];
    }

    registerAll() {}

    launch(appId, params = {}) {
        const app = this.apps.find(a => a.id === appId);
        if (!app) return;

        let appInstance;
        if (appId === 'todo') appInstance = new TodoApp(this.kernel);
        else if (appId === 'explorer') appInstance = new FileExplorerApp(this.kernel);
        else if (appId === 'notepad') appInstance = new NotepadApp(this.kernel);
        else if (appId === 'terminal') appInstance = new TerminalApp(this.kernel);
        else if (appId === 'browser') appInstance = new BrowserApp(this.kernel);
        else if (appId === 'settings') appInstance = new SettingsApp(this.kernel);

        if (appInstance) {
            this.kernel.ui.createWindow(app.name, '', app.id);
            setTimeout(() => {
                const win = document.getElementById(`window-${appId}`);
                if (win) {
                    appInstance.render(win.querySelector('.window-content'), params);
                    this.kernel.processManager.startProcess(appId, app);
                }
            }, 50);
        }
    }
}

