/**
 * File Explorer App
 */
export class FileExplorerApp {
    constructor(kernel) {
        this.kernel = kernel;
    }
    render(container) {
        container.innerHTML = '<div class="file-explorer"><div class="explorer-toolbar"><button onclick="Kernel.fs.mkdir(\'new_folder\')">New Folder</button><button onclick="Kernel.fs.createFile(\'file.txt\')">New File</button></div><div id="explorer-files" class="explorer-content"></div></div>';
        this.refresh();
    }
    refresh() {
        const list = document.getElementById('explorer-files');
        if (!list) return; list.innerHTML = '';
        Object.keys(this.kernel.fs.root.children).forEach(name => {
            const item = this.kernel.fs.root.children[name];
            const div = document.createElement('div');
            div.className = `file-item ${item.type}`;
            div.innerHTML = `<span>${item.type === 'dir' ? '📁' : '📄'}</span><span>${name}</span>`;
            div.onclick = () => item.type === 'file' ? this.kernel.apps.launch('notepad', { filename: name }) : null;
            list.appendChild(div);
        });
    }
}

