/**
 * Todo App
 */
export class TodoApp {
    constructor(kernel) {
        this.kernel = kernel;
    }
    render(container) {
        container.innerHTML = '<div class="todo-container"><div class="todo-input-group"><input type="text" id="new-task" placeholder="Task..."><button id="add-task-btn" class="btn-primary">+</button></div><ul id="todo-list"></ul></div>';

        const fs = this.kernel.fs;
        let tasks = [];
        const todoFile = 'documents/todo.json';

        const loadTasks = () => {
            const parts = todoFile.split('/');
            const dir = fs.root.children[parts[0]];
            if (dir && dir.children[parts[1]]) {
                try {
                    tasks = JSON.parse(dir.children[parts[1]].content);
                } catch(e) { tasks = []; }
            }
        };

        const saveTasks = () => {
            fs.writeFile(todoFile, JSON.stringify(tasks));
        };

        const renderTasks = () => {
            const list = document.getElementById('todo-list');
            if (!list) return;
            list.innerHTML = '';
            tasks.forEach((task, index) => {
                const li = document.createElement('li');
                li.className = 'todo-item' + (task.completed ? ' completed' : '');
                li.innerHTML = `<span>${task.text}</span><button class="del-task">✕</button>`;
                li.querySelector('.del-task').onclick = (e) => {
                    e.stopPropagation();
                    tasks.splice(index, 1);
                    renderTasks();
                    saveTasks();
                };
                li.querySelector('span').onclick = () => {
                    tasks[index].completed = !tasks[index].completed;
                    renderTasks();
                    saveTasks();
                };
                list.appendChild(li);
            });
        };

        document.getElementById('add-task-btn').onclick = () => {
            const input = document.getElementById('new-task');
            const val = input.value;
            if (val.trim()) {
                tasks.push({ text: val, completed: false });
                input.value = '';
                renderTasks();
                saveTasks();
            }
        };

        loadTasks();
        renderTasks();
    }
}

