/**
 * Process Manager
 */
export class ProcessManager {
    constructor(kernel) {
        this.kernel = kernel;
        this.processes = new Map();
    }
    startProcess(appId, processInfo) {
        this.processes.set(appId, processInfo);
        this.kernel.ui.updateTaskbar();
    }
    stopProcess(appId) {
        this.processes.delete(appId);
        this.kernel.ui.updateTaskbar();
    }
    getRunningApps() {
        return Array.from(this.processes.entries()).map(([id, info]) => ({ id, name: info.name }));
    }
}

