/**
 * UI Controller
 */
export class UIController {
    constructor(kernel) {
        this.kernel = kernel;
        this.contextMenu = document.getElementById('context-menu');
        this.zIndexCounter = 100;
    }

    init() {
        this.updateClock();
        setInterval(() => this.updateClock(), 1000);
        const loader = document.getElementById('loading-screen');
        if (loader) loader.style.display = 'none';
        document.addEventListener('click', (e) => this.hideContextMenu(e));
        document.addEventListener('contextmenu', (e) => {
            e.preventDefault();
            this.showContextMenu(e.clientX, e.clientY);
        });
        this.initSearch();
    }

    initSearch() {
        const searchInput = document.getElementById('start-search');
        if (!searchInput) return;
        searchInput.addEventListener('input', (e) => {
            const term = e.target.value.toLowerCase();
            const items = document.querySelectorAll('.start-item');
            items.forEach(item => {
                const text = item.textContent.toLowerCase();
                item.style.display = text.includes(term) ? 'block' : 'none';
            });
        });
    }

    updateClock() {
        const clockEl = document.getElementById('clock');
        if (clockEl) clockEl.textContent = new Date().toLocaleTimeString();
    }

    toggleStartMenu() {
        document.getElementById('start-menu').classList.toggle('hidden');
    }

    showContextMenu(x, y) {
        this.contextMenu.style.top = x + 'px';
        this.contextMenu.style.left = y + 'px';
        this.contextMenu.classList.remove('hidden');
    }

    hideContextMenu(e) {
        this.contextMenu.classList.add('hidden');
    }

    updateTaskbar() {
        const container = document.getElementById('running-apps');
        if (!container) return;
        container.innerHTML = '';
        this.kernel.processManager.getRunningApps().forEach(app => {
            const btn = document.createElement('button');
            btn.className = 'taskbar-item';
            btn.textContent = app.name;
            btn.onclick = () => this.focusWindow(app.id);
            container.appendChild(btn);
        });
    }

    focusWindow(appId) {
        const win = document.getElementById('window-' + appId);
        if (win) {
            if (win.style.display === 'none') {
                win.style.display = 'flex';
            }
            if (win.dataset.maximized === 'true') {
                win.style.width = '';
                win.style.height = '';
                win.style.top = '';
                win.style.left = '';
                win.dataset.maximized = 'false';
            }
            this.zIndexCounter++;
            win.style.zIndex = this.zIndexCounter;
        }
    }

    createWindow(title, content, appId) {
        const desktop = document.getElementById('desktop');
        const win = document.createElement('div');
        win.className = 'window';
        win.id = 'window-' + appId;
        win.style.zIndex = ++this.zIndexCounter;
        win.innerHTML = '<div class="window-header">' +
            '<span class="window-title">' + title + '</span>' +
            '<div class="window-controls">' +
                '<button class="control-btn btn-min">_</button>' +
                '<button class="control-btn btn-max">□</button>' +
                '<button class="control-btn btn-close">✕</button>' +
            '</div>' +
            '</div>' +
            '<div class="window-content"></div>';

        win.querySelector('.window-header').onmousedown = (e) => {
            if (e.target.className === 'window-title' || e.target.parentElement.className === 'window-header') {
                this.makeDraggable(win, win.querySelector('.window-header'));
            }
        };

        win.querySelector('.btn-close').onclick = () => {
            win.remove();
            this.kernel.processManager.stopProcess(appId);
        };
        win.querySelector('.btn-min').onclick = () => this.minimizeWindow(appId);
        win.querySelector('.btn-max').onclick = () => this.maximizeWindow(appId);

        win.onmousedown = () => this.focusWindow(appId);

        desktop.appendChild(win);
        return win;
    }

    minimizeWindow(appId) {
        const win = document.getElementById('window-' + appId);
        if (win) {
            win.style.display = 'none';
            win.dataset.minimized = 'true';
        }
    }

    maximizeWindow(appId) {
        const win = document.getElementById('window-' + appId);
        if (win) {
            if (win.dataset.maximized === 'true') {
                win.style.width = '';
                win.style.height = '';
                win.style.top = '';
                win.style.left = '';
                win.dataset.maximized = 'false';
            } else {
                win.style.width = '100%';
                win.style.height = 'calc(100vh - 45px)';
                win.style.top = '0';
                win.style.left = '0';
                win.dataset.maximized = 'true';
            }
        }
    }

    makeDraggable(win, header) {
        let offsetX = 0, offsetY = 0;
        header.onmousedown = (e) => {
            const startX = e.clientX;
            const startY = e.clientY;
            offsetX = e.clientX - win.offsetLeft;
            offsetY = e.clientY - win.offsetTop;

            const onMove = (e) => {
                win.style.left = (e.clientX - offsetX) + 'px';
                win.style.top = (e.clientY - offsetY) + 'px';
                win.style.margin = '0';
            };
            const onUp = () => {
                document.removeEventListener('mousemove', onMove);
                document.removeEventListener('mouseup', onUp);
            };
            document.addEventListener('mousemove', onMove);
            document.addEventListener('mouseup', onUp);
        };
    }

    changeWallpaper() {
        const colors = ['#2c3e50', '#e74c3c', '#27ae60', '#2980b9', '#8e44ad', '#f39c12'];
        const color = colors[Math.floor(Math.random() * colors.length)];
        document.body.style.background = 'linear-gradient(45deg, ' + color + ', #000)';
    }
}
